/** A read's path, asking for the sheet as of the date when one is set. */
export function readPath(path: string, asOf: string): string {
  return asOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;
}

